const $=s=>document.querySelector(s);const params=new URLSearchParams(location.search);let screen=params.get('screen')||'home',mood='Mountains';const referenceFixture=window.awayReferenceFixtures?.[params.get('reference')];let state;if(referenceFixture){state=JSON.parse(JSON.stringify(referenceFixture))}else{try{state=JSON.parse(localStorage.getItem('away-trip'))}catch{}}state=state||{cities:[],start:'',end:'',pace:'Balanced',activities:{},saved:false};const cities=[['Paris','France','♜'],['Interlaken','Switzerland','△'],['Amsterdam','Netherlands','⌂'],['Rome','Italy','♜'],['Venice','Italy','≈'],['Barcelona','Spain','☀'],['Tokyo','Japan','♜'],['Bali','Indonesia','≈'],['London','United Kingdom','⌂'],['Lisbon','Portugal','☀']];const moods=[['Mountains','△','green'],['Beaches','≈','teal'],['Architecture','♜','red'],['New year escapes','✳','blue']];const names={home:'Explore',destinations:'Destinations',dates:'Dates',trip:'Your trip',inspiration:'Inspiration',saved:'Saved trips',planning:'Plan each city'};function persist(){if(!referenceFixture)localStorage.setItem('away-trip',JSON.stringify(state))}function go(s){screen=s;const u=new URL(location);u.searchParams.set('screen',s);history.pushState({},'',u);render()}window.onpopstate=()=>{screen=new URLSearchParams(location.search).get('screen')||'home';render()};function header(title,back){return `<header>${back?`<button class="back" data-go="${back}" aria-label="Go back"><img src="assets/reference/city-imgAwayChevronLeft.svg" width="20" height="20" alt=""></button>`:'<span aria-hidden="true"></span>'}<span>${title||''}</span>${back?'':'<span class="avatar">A</span>'}</header>`}function nav(){return ''}function footer(label,action,disabled=false){return `<div class="footer"><button class="primary" data-action="${action}" ${disabled?'disabled':''}>${label}</button></div>`}function stamp(label,symbol,color='blue'){return `<div class="stamp ${color}"><div class="stamp-inner"><small>YOUR NEXT CHAPTER</small><strong>${symbol}</strong><b>${label}</b><small>ADMIT ONE · GO SOMEWHERE</small></div></div>`}function render(){const destinationEntry=screen==='destinations'&&lastRenderedScreen!=='destinations',tripEntry=screen==='trip'&&lastRenderedScreen!=='trip';lastRenderedScreen=screen;document.querySelector('.home-tap-hint')?.remove();document.querySelector('.phone').classList.toggle('figma-home-phone',screen==='home');document.body.classList.toggle('embed',params.get('embed')==='1'||$('#embed').checked);$('#screen-links').innerHTML=Object.entries(names).map(([k,v])=>`<button data-go="${k}" class="${screen===k?'active':''}">${v}</button>`).join('');let html='';if(screen==='home'){html=figmaHome()}else if(screen==='destinations'){html=header('', 'home')+`<div class="content destination-content"><h2>Where are<br>you heading?</h2>${selectedCityList()}<div class="destination-search"><label class="destination-section-label" for="search">${state.cities.length?'Add another city':'Explore cities'}</label><input class="search" id="search" placeholder="Search cities or countries" aria-label="Search cities or countries"><div class="cities" aria-label="Unselected cities">${cityList('')}</div></div><p class="sr-only" id="route-announcement" aria-live="polite"></p></div>`+footer(state.cities.length?'Proceed to choose dates':'Choose a place to continue','dates',!state.cities.length)}else if(screen==='dates'){html=header('','destinations')+`<div class="content"><h2>Choose dates</h2>${calendarPicker()}<p id="date-error" role="alert" class="muted"></p></div>`+footer('Build an intinrary','build')}else if(screen==='planning'){html=cityPlanning()}else if(screen==='trip'){html=tripCityList()}else if(screen==='inspiration'){const options=mood==='Mountains'?['Interlaken']:mood==='Beaches'?['Bali']:mood==='Architecture'?['Paris','Rome','Barcelona']:['Tokyo','Amsterdam'];html=header('','home')+`<div class="content"><p class="eyebrow">EXPLORE BY INTEREST</p><h2>${mood}</h2><p class="muted">Somewhere that feels like you.</p>${options.map((c,i)=>`<section class="inspo">${stamp(c,cities.find(x=>x[0]===c)[2],['green','red','teal'][i%3])}<div><h3>${c}</h3><p class="muted">${mood==='Mountains'?'Alpine views and unhurried days.':mood==='Beaches'?'Salty air and a slower rhythm.':'A different view around every corner.'}</p><button class="linkbtn" data-pick="${c}">Plan a trip here</button></div></section>`).join('')}<p class="muted">Editorial demo ideas, not live recommendations.</p></div>`+nav()}else{html=header()+`<div class="content"><p class="eyebrow">THE CHAPTERS AHEAD</p><h2>My trips</h2>${state.saved?`<section class="saved">${stamp(state.cities[0]||'Away','✳','green')}<h3>${state.title||'Europe 2026'}</h3><p class="muted">${state.start} · Saved on this device</p><button class="primary" data-go="trip">Open trip</button></section>`:`<div class="note">Your next story is waiting. Create a trip and save it here.</div><button class="primary" data-action="new-trip">Create a trip</button>`}</div>`+nav()}$('.phone').classList.toggle('figma-planning-phone',['planning','trip'].includes(screen));$('.phone').classList.remove('has-route-map');$('.phone').classList.toggle('destination-picker-phone',screen==='destinations');$('.phone').classList.toggle('date-picker-phone',screen==='dates');$('#app').classList.toggle('no-bottom-nav',['home','inspiration','saved','trip'].includes(screen));$('#app').innerHTML=html;restoreCheckInOrder();$('#app').scrollTop=0;persist();if(typeof renderBookingLayer==='function')renderBookingLayer();if(screen==='destinations'){revealDestinationPhotos();if(destinationEntry)animateDestinationEntry()}if(tripEntry)animateTripEntry()}
let destinationAnimations=[];
function destinationMotionNodes(){return [...document.querySelectorAll('.selected-city-stop,.cities [data-city],.destination-section-label,#search')].map(node=>({node,key:node.dataset.routeCity?'selected:'+node.dataset.routeCity:node.dataset.city?'available:'+node.dataset.city:node.id||'search-label'}));}
function selectableDestination(city){return ['Paris','Interlaken','Amsterdam'].includes(city)}
function toggleDestinationCity(city){
 if(!selectableDestination(city)&&!state.cities.includes(city))return;
 destinationAnimations.forEach(animation=>animation.finish());destinationAnimations=[];
 const app=$('#app'),scroll=app.scrollTop,query=$('#search')?.value||'',adding=!state.cities.includes(city);
 const source=adding?document.querySelector(`.cities [data-city="${city}"]`):document.querySelector(`[data-route-city="${city}"] .selected-city-card`);
 const from=source?.getBoundingClientRect(),previous=new Map(destinationMotionNodes().map(({node,key})=>[key,node.getBoundingClientRect()]));
 state.cities=adding?[...state.cities,city]:state.cities.filter(c=>c!==city);render();
 if(screen!=='destinations')return;
 $('#search').value=query;$('.cities').innerHTML=cityList(query);app.scrollTop=scroll;
 const target=adding?document.querySelector(`[data-route-city="${city}"] .selected-city-card`):document.querySelector(`.cities [data-city="${city}"]`);
 if(adding&&target){const bounds=app.getBoundingClientRect(),box=target.getBoundingClientRect();if(box.top<bounds.top+12||box.bottom>bounds.bottom-100)app.scrollTop+=box.top-bounds.top-70;}
 const focus=adding?document.querySelector(`[data-route-city="${city}"] .remove-selected-city`):target||$('#search');focus?.focus({preventScroll:true});
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const timing={duration:560,easing:'cubic-bezier(.22,1,.36,1)'};
 for(const {node,key} of destinationMotionNodes()){
  if((adding&&key==='selected:'+city)||(!adding&&key==='available:'+city))continue;
  const before=previous.get(key),after=node.getBoundingClientRect();
  if(before){const dx=before.left-after.left,dy=before.top-after.top;if(Math.abs(dx)+Math.abs(dy)>1)destinationAnimations.push(node.animate([{transform:`translate(${dx}px,${dy}px)`},{transform:'translate(0,0)'}],timing));}
  else destinationAnimations.push(node.animate([{opacity:0},{opacity:1}],{duration:280,delay:160,fill:'backwards'}));
 }
 if(target&&from){const to=target.getBoundingClientRect();target.style.position='relative';target.style.zIndex='3';const animation=target.animate([{transformOrigin:'top left',transform:`translate(${from.left-to.left}px,${from.top-to.top}px) scale(${from.width/to.width},${from.height/to.height})`,boxShadow:'0 10px 24px #334d6826'},{transformOrigin:'top left',transform:'translate(0,0) scale(1)',boxShadow:'0 0 0 #334d6800'}],{duration:620,easing:'cubic-bezier(.22,1,.36,1)'});destinationAnimations.push(animation);animation.finished.catch(()=>{}).finally(()=>{target.style.position='';target.style.zIndex='';});}
 const heading=document.querySelector('.selected-cities-heading');if(adding&&state.cities.length===1&&heading)destinationAnimations.push(heading.animate([{opacity:0,transform:'translateY(-8px)'},{opacity:1,transform:'translateY(0)'}],{duration:300,delay:180,fill:'backwards'}));
}
function selectedCityList(){
 if(!state.cities.length)return '';
 return `<section class="selected-cities" aria-labelledby="selected-cities-heading"><div class="selected-cities-heading"><h3 id="selected-cities-heading">Your route</h3><span>${state.cities.length} ${state.cities.length===1?'city':'cities'}</span></div><ol class="selected-city-timeline">${state.cities.map((c,i)=>{const country=cities.find(city=>city[0]===c)?.[1]||'';return `<li class="selected-city-stop" data-route-city="${c}"><span class="selected-route-number" aria-hidden="true">${i+1}</span><div class="selected-city-card"><img class="city-photo" src="${citySearchPhoto(c)}" alt="" width="48" height="48"><span class="selected-city-name"><b>${c}</b><small>${country}</small></span><button class="remove-selected-city" data-city="${c}" aria-label="Remove ${c}">×</button>${state.cities.length>1?`<button class="city-drag-handle" data-reorder-city="${c}" aria-label="Reorder ${c}. Use up and down arrow keys to move."><svg width="20" height="24" viewBox="0 0 20 24" fill="currentColor" aria-hidden="true"><circle cx="7" cy="6" r="1.5"/><circle cx="13" cy="6" r="1.5"/><circle cx="7" cy="12" r="1.5"/><circle cx="13" cy="12" r="1.5"/><circle cx="7" cy="18" r="1.5"/><circle cx="13" cy="18" r="1.5"/></svg></button>`:''}</div></li>`}).join('')}</ol></section>`;
}
function citySearchPhoto(city){const index=['Paris','Interlaken','Rome','Amsterdam','Venice','Barcelona','Tokyo','Bali','London','Lisbon'].indexOf(city);return index<0?'assets/cities/'+city.toLowerCase()+'.jpg':'assets/reference/city-imgCityPhoto'+(index||'')+'.png'}
function cityList(q){const filtered=cities.filter(c=>!state.cities.includes(c[0])&&c.slice(0,2).join(' ').toLowerCase().includes(q.toLowerCase()));return filtered.map(([c,country,icon])=>`<button class="city ${state.cities.includes(c)?'checked':''}" data-city="${c}" ${selectableDestination(c)?'':'disabled aria-label="'+c+', placeholder destination"'} aria-pressed="${state.cities.includes(c)}"><img class="city-photo" src="${citySearchPhoto(c)}" alt="${c}" width="56" height="56"><span><b>${c}</b><small>${country}</small></span></button>`).join('')||(q?'<p class="muted">No unselected cities match your search.</p>':'<p class="muted">All cities have been added to your trip.</p>')}document.addEventListener('input',e=>{if(e.target.id==='search')$('.cities').innerHTML=cityList(e.target.value);if(['start','end'].includes(e.target.id)){state[e.target.id]=e.target.value;if(e.target.id==='start')$('#end').min=e.target.value;persist()}});document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.action==='new-trip'){startNewTrip();return;}if(d.go){if(d.go==='trip')expandedTripCity=null;go(d.go);}if(d.city)toggleDestinationCity(d.city);if(d.mood){mood=d.mood;go('inspiration')}if(d.pick){state.cities=[d.pick];go('destinations')}if(d.pace){state.pace=d.pace;render()}if(d.suggestion)togglePlanningActivity(b);if(d.action==='next-city'){const range=state.cityDates?.[state.cities[state.planningIndex||0]];if(!cityEndSelected(range))return;if((state.planningIndex||0)<state.cities.length-1){transitionCity((state.planningIndex||0)+1)}else{state.saved=true;go('trip')}}if(d.action==='previous-city'){if(state.planningIndex>0){transitionCity(state.planningIndex-1)}else go('dates')}if(d.editCity!==undefined){state.planningIndex=Number(d.editCity);go('planning')}if(d.action==='dates')go('dates');if(d.action==='build'){if(!state.cities.length){go('destinations');return}if(!state.start||!state.end||state.end<state.start){$('#date-error').textContent='Choose a departure and a return date after it.';return}state.title='Europe 2026';state.planningIndex=0;prepareCityPlans();persist();go('planning')}if(d.action==='save'){state.saved=true;persist();go('saved')}if(d.add){state.activities[d.add]??=[];const suggestions=['A local food walk','A quiet morning at a café','Explore a local museum','An afternoon at the market'];const next=suggestions.find(a=>!state.activities[d.add].includes(a));if(next)state.activities[d.add].push(next);render()}if(d.remove){const [c,j]=d.remove.split('|');state.activities[c].splice(+j,1);render()}});$('#embed').checked=params.get('embed')==='1';$('#embed').onchange=()=>render();$('#copy').onclick=async()=>{const u=new URL(location);u.searchParams.set('embed','1');try{await navigator.clipboard.writeText(`<iframe src="${u}" title="Away travel prototype" width="390" height="844" style="border:0;border-radius:24px" loading="lazy"></iframe>`);$('#copied').textContent='Embed code copied'}catch{$('#copied').textContent='Use ?embed=1&screen='+screen+' in your iframe URL'}};

const cityIdeas={Paris:['Walk along the Seine','Explore the Louvre','Spend a morning in Montmartre','Find a neighbourhood pâtisserie'],Interlaken:['Walk beside Lake Brienz','Explore Unterseen old town','Walk through Höhematte park'],Rome:['Explore the Roman Forum','Wander through Trastevere','Visit the Pantheon'],Amsterdam:['Walk the canal ring','Explore the Rijksmuseum','Browse the Jordaan'],Venice:['Explore the canals','Visit the Doge’s Palace','Wander through Cannaregio'],Barcelona:['Explore Park Güell','Visit the Sagrada Família','Walk the Gothic Quarter'],Tokyo:['Explore Asakusa','Browse the shops in Shibuya','Visit Meiji Jingu'],Bali:['Explore Ubud','Spend an afternoon by the sea','Visit the rice terraces'],London:['Explore the British Museum','Walk along the South Bank','Browse Borough Market'],Lisbon:['Wander through Alfama','Visit Belém','Watch the sunset from a miradouro']};
function cityEndSelected(range){return !!range?.end&&range.endChosen===range.end&&range.end>=range.start&&range.end<=state.end}
function prepareCityPlans(){
 state.activities??={};state.cityDates??={};for(const c of state.cities){state.activities[c]=(state.activities[c]||[]).filter(a=>!['Settle in & explore the neighbourhood','Leave a little room to wander'].includes(a))}
 const key=[state.start,state.end,...state.cities].join('|');
 if(state.cityDatesKey===key){for(const [i,c] of state.cities.entries()){const r=state.cityDates[c];if(!r)continue;if(i===state.cities.length-1){r.end=state.end;r.endChosen=state.end}else if(!r.endChosen)r.end=''}return;}
 const total=Math.round((parseDay(state.end)-parseDay(state.start))/86400000)+1;
 state.cities.forEach((c,i)=>{const offset=Math.min(total-1,Math.floor(total*i/state.cities.length));const endOffset=Math.max(offset,Math.min(total-1,Math.floor(total*(i+1)/state.cities.length)-1));const a=parseDay(state.start),b=parseDay(state.start);a.setDate(a.getDate()+offset);b.setDate(b.getDate()+endOffset);state.cityDates[c]={start:localDate(a),end:i===state.cities.length-1?state.end:'',endChosen:i===state.cities.length-1?state.end:''};state.activities[c]??=[]});
 state.cityDatesKey=key;
}
function cityPlanning(){
 if(!state.cities.length||!state.start||!state.end)return header('','dates')+'<div class="content"><h2>Choose your cities and dates</h2><button class="primary" data-go="destinations">Plan a trip</button></div>';
 prepareCityPlans();const i=Math.min(state.planningIndex||0,state.cities.length-1),c=state.cities[i];state.planningIndex=i;const range=state.cityDates[c];
 const photo=cityCoverPhoto(c);
 return `<div class="content city-planning figma-planning"><div class="planning-top-navigation"><button class="planning-back" data-action="previous-city" aria-label="${i?'Previous city':'Back to dates'}">${chevron()}</button><button class="figma-close" data-go="home" aria-label="Close trip"><img src="assets/figma/close.svg" alt=""></button></div><div class="figma-trip-heading"><h2>${state.title||'Europe 2026'}</h2><p class="planning-trip-dates">${dateLabel(state.start)} – ${dateLabel(state.end)}</p></div>${planningRoute(i)}<div class="planning-cover"><img src="${photo}" alt="${c}"><h1>${c}</h1></div>${cityDateRow(c,range)}${cityArticle(c)}</div><div class="footer planning-footer">${!cityEndSelected(range)?'<p class="planning-date-hint" id="planning-date-hint" role="status">Pick a departure date to continue</p>':''}<button class="primary" data-action="next-city" ${!cityEndSelected(range)?'disabled aria-describedby="planning-date-hint"':''}>Next</button></div>`;

}
function cityDateRow(c,range){
 let days='';for(let d=parseDay(state.start),last=parseDay(state.end);d<=last;d.setDate(d.getDate()+1)){const iso=localDate(d),edge=iso===range.start||iso===range.end,inside=!!range.end&&iso>=range.start&&iso<=range.end;
 days+=`<button class="city-date ${edge?'endpoint':''} ${iso===range.start?'arrival':''} ${inside?'in-range':''}" data-planning-day="${iso}" ${iso<range.start?'disabled':''} aria-pressed="${edge||inside}" aria-label="${dateLabel(iso)}${iso===range.start?', arrival':''}${iso===range.end?', departure':''}"><small>${d.toLocaleDateString('en-GB',{weekday:'short'})}</small><strong>${d.getDate()}</strong><small>${d.toLocaleDateString('en-GB',{month:'short'})}</small></button>`}
 return `<section class="city-date-picker" aria-label="Choose dates in ${c}"><h3 class="date-rail-heading">Select dates</h3><div class="city-date-row">${days}</div></section>`;
}
function cityInsight(c,range){
 const month=parseDay(range.start).getMonth()+1,win=month>=11||month<=2;
 const length=range.end?Math.round((parseDay(range.end)-parseDay(range.start))/86400000)+1:1;
 let text=win?'Plan outdoor stops in daylight and keep an indoor option for later.':'Choose one main sight each day, then leave room to explore the neighbourhood around it.';
 let source='';
 if(c==='Paris'&&win){text='Pair a museum afternoon with a daytime Seine walk and a cosy café stop. A flexible mix of indoor and outdoor plans suits this time of year.';source='https://parisjetaime.com/eng/article/what-to-do-in-paris-in-winter-a1819'}
 if(c==='Amsterdam'&&win){text='Winter is usually quieter at the major museums. Combine the Rijksmuseum with a short canal walk and a warm café stop.';source='https://www.iamsterdam.com/en/explore/winter-in-amsterdam/reasons-to-visit-amsterdam-in-winter'}
 if(c==='Interlaken'&&win){text='Keep your mountain day flexible and check local conditions before heading up. Save a relaxed lakeside or town day as an alternative.'}
 if(c==='Bali'){text='Balance a day of exploring with unhurried time near where you stay. Leave flexibility for outdoor plans and local conditions.'}
 if(length<=2)text+=' With '+length+(length===1?' day':' days')+', keep your shortlist small.';
 if((month===12&&Number(range.start.slice(8))>=20)||(month===1&&Number(range.start.slice(8))<=2))text+=' Check holiday opening hours before choosing your stops.';
 return `<aside class="planning-insight" aria-label="Date-based planning insight"><div class="insight-label"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/></svg><b>AI insight</b><span>${parseDay(range.start).toLocaleDateString('en-GB',{month:'short'})}</span></div><p>${text}</p><small>Seasonal guidance${source?` · <a href="${source}" target="_blank" rel="noopener">City guide</a>`:''}</small></aside>`;
}
const activityPhotos={"Explore the Louvre": "louvre", "Visit the Musée d’Orsay": "orsay", "Discover the Musée de l’Orangerie": "orangerie", "Walk up to Sacré-Cœur": "sacre-coeur", "Wander Rue de l’Abreuvoir": "abreuvoir", "Visit the Musée Montmartre": "montmartre", "Explore Place du Tertre": "tertre", "Relax in Place des Vosges": "vosges", "Browse the Marais boutiques": "marais", "Explore Rue de Bretagne": "bretagne", "Lunch at Enfants Rouges": "market", "Browse Rue Montorgueil": "montorgueil", "Pick up a bakery breakfast": "bakery", "Try the stalls at Enfants Rouges": "market", "Plan a neighbourhood bistro dinner": "bistro"};
function cityArticle(c){
 const art=['Art & iconic sights','Make time for the places that tell the story of Paris, from celebrated collections to its unmistakable skyline.',['Explore the Louvre','Visit the Musée d’Orsay','See the Eiffel Tower','Discover the Musée de l’Orangerie']];
 const groups=c==='Paris'?[
 ['Art & iconic sights','Start with the Louvre’s Denon wing for celebrated masterpieces, spend another afternoon with the Impressionists at Orsay, or slow down in front of Monet’s Water Lilies at the Orangerie. Choose one museum at a time and leave room to linger.',['Explore the Louvre','Visit the Musée d’Orsay','Discover the Musée de l’Orangerie']],
 ['Montmartre, at your own pace','Head up to Sacré-Cœur for the view, then explore the smaller streets around the hill. The Musée Montmartre adds former artists’ studios and a garden to a neighbourhood walk.',['Walk up to Sacré-Cœur','Wander Rue de l’Abreuvoir','Visit the Musée Montmartre','Explore Place du Tertre']],
 ['An afternoon in the Marais','Start at Place des Vosges, browse the boutiques and historic streets, then follow Rue de Bretagne towards the Marché des Enfants Rouges. This is a neighbourhood to explore on foot, with plenty of reasons to pause.',['Relax in Place des Vosges','Browse the Marais boutiques','Explore Rue de Bretagne','Lunch at Enfants Rouges']],
 ['Eat your way around Paris','Make Rue Montorgueil your starting point for food shops, bakeries and café terraces. Pair a pastry stop with a market lunch, then leave an evening free for a bistro you discover along the way.',['Browse Rue Montorgueil','Pick up a bakery breakfast','Try the stalls at Enfants Rouges','Plan a neighbourhood bistro dinner']]
 ]:[['Discover '+c,'Explore the sights and everyday pleasures of the city.',cityIdeas[c]||['Explore the old town','Try the local food','Visit a local museum']]];
 return `<article class="city-article"><p class="guide-eyebrow">CITY GUIDE</p><h2>Things to do in ${c}</h2><p class="guide-intro">${c==='Paris'?'Art-filled afternoons, winding streets and something delicious around every corner. Find your kind of Paris, and add a few favourites to your itinerary.':c==='Amsterdam'?'Canals lined with narrow gabled houses, world-famous art and a city that moves by bicycle. Discover Rembrandt and Van Gogh, wander the Jordaan, and pause at a cosy brown café between waterside walks.':'Find your favourite experiences and add them to your itinerary.'}</p>${groups.map(([title,description,ideas])=>`<section class="guide-category"><h3>${title}</h3><p>${description}</p><div class="planning-suggestions">${ideas.map(a=>{const selected=(state.activities[c]||[]).includes(a);return `<button data-suggestion="${a}" aria-pressed="${selected}" class="planning-suggestion ${selected?'selected':''}"><img class="activity-thumbnail" src="${activityPhotos[a]?'assets/activities/'+activityPhotos[a]+'.jpg':cityCoverPhoto(c)}" alt="" width="56" height="56" loading="lazy"><span class="activity-label">${a}</span><span class="suggestion-plus" aria-hidden="true">${selected?'<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12 4 4L19 6"/></svg>':'<img src="assets/figma/add.svg" width="18" height="18" alt="">'}</span><span class="sr-only">${selected?'Remove from itinerary':'Add to itinerary'}</span></button>`}).join('')}</div></section>`).join('')}${c==='Paris'?'<p class="guide-sources">Photos: <a href="activity-photo-credits.html" target="_blank" rel="noopener">credits</a><br>Explore more: <a href="https://parisjetaime.com/eng/article/montmartre-village-in-paris-a728" target="_blank" rel="noopener">Montmartre</a> · <a href="https://parisjetaime.com/eng/article/a-walk-in-the-marais-a838" target="_blank" rel="noopener">The Marais</a> · <a href="https://www.louvre.fr/en/explore/visitor-trails/the-louvre-s-masterpieces" target="_blank" rel="noopener">Louvre</a> · <a href="https://www.musee-orangerie.fr/en/node/33" target="_blank" rel="noopener">Orangerie</a></p>':''}</article>`;
}
document.addEventListener('click',e=>{
 const day=e.target.closest('[data-planning-day]')?.dataset.planningDay;if(!day)return;
 const c=state.cities[state.planningIndex||0];const r=state.cityDates[c];if(day<r.start||day>state.end)return;r.end=day;r.endChosen=day;
 const scroll=document.querySelector('#app').scrollTop;const left=document.querySelector('.city-date-row').scrollLeft;persist();render();document.querySelector('#app').scrollTop=scroll;document.querySelector('.city-date-row').scrollLeft=left;document.querySelector(`[data-planning-day="${day}"]`)?.focus({preventScroll:true});
});



document.addEventListener("click",e=>{const b=e.target.closest("[data-planning-city]");if(b){transitionCity(Number(b.dataset.planningCity))}});


function routeVector(kind){
 const shape=kind==='up'?'M1 34L16 8H56':kind==='down'?'M1 8H41L56 34':'M1 8H30';
 const width=kind==='flat'?32:58;
 const dot=kind==='down'?1:kind==='flat'?30:56;
 return `<svg class="route-vector ${kind}" width="${width}" height="34" viewBox="0 0 ${width} 34" fill="none" aria-hidden="true"><path d="${shape}" pathLength="1" stroke="#1a1a1a" stroke-width="1"/><circle cx="${dot}" cy="8" r="2.5" fill="#1a1a1a"/></svg>`;
}
function planningRoute(index){
 let html='';for(let j=0;j<state.cities.length;j++){
 if(j===index){if(j>0)html+=routeVector('down');if(j<state.cities.length-1)html+=routeVector('up');continue}
 html+=`<button data-planning-city="${j}">${state.cities[j]}</button>`;
 if(j<state.cities.length-1&&j+1!==index)html+=routeVector('flat');
 }
 return `<nav class="figma-route morph-route" aria-label="Trip cities">${html}</nav>`;
}
let cityMotionFrame=0,cityTransitionBusy=false;
function motionText(node){if(!node)return null;const box=node.getBoundingClientRect(),style=getComputedStyle(node);return {text:node.textContent,box,fontSize:parseFloat(style.fontSize),fontFamily:style.fontFamily,fontWeight:style.fontWeight,lineHeight:style.lineHeight,color:style.color}}
function morphCityLabel(from,to){
 if(!from||!to)return Promise.resolve();const target=motionText(to);const ghost=document.createElement('span');ghost.textContent=from.text;
 Object.assign(ghost.style,{position:'fixed',left:from.box.left+'px',top:from.box.top+'px',fontFamily:from.fontFamily,fontSize:from.fontSize+'px',fontWeight:from.fontWeight,lineHeight:from.lineHeight,color:from.color,whiteSpace:'nowrap',pointerEvents:'none',zIndex:1000,transformOrigin:'top left'});
 document.body.appendChild(ghost);to.style.visibility='hidden';
 const animation=ghost.animate([{transform:'translate(0,0) scale(1)',color:from.color},{transform:`translate(${target.box.left-from.box.left}px,${target.box.top-from.box.top}px) scale(${target.fontSize/from.fontSize})`,color:target.color}],{duration:720,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'});
 return animation.finished.catch(()=>{}).finally(()=>{ghost.remove();to.style.visibility=''})
}
async function transitionCity(index){
 if(cityTransitionBusy||index===state.planningIndex||index<0||index>=state.cities.length)return;
 cityTransitionBusy=true;cancelAnimationFrame(cityMotionFrame);
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,previous=state.planningIndex||0;
 const app=document.querySelector('#app');if(app)app.scrollTop=0;
 const incoming=motionText(document.querySelector(`[data-planning-city="${index}"]`));
 const outgoing=motionText(document.querySelector('.planning-cover h1'));
 const retainedRail=document.querySelector('.city-date-row');const previousLeft=retainedRail?.scrollLeft||0;
 const departure=state.cityDates?.[state.cities[previous]]?.end;
 const positions=new Map([...document.querySelectorAll('[data-planning-city]')].map(n=>[n.dataset.planningCity,n.getBoundingClientRect()]));
 try{
 if(!reduced)await Promise.all([...document.querySelectorAll('.route-vector path')].map(n=>n.animate([{strokeDasharray:'1',strokeDashoffset:0},{strokeDasharray:'1',strokeDashoffset:1}],{duration:180,easing:'ease-in',fill:'forwards'}).finished));
 if(index===previous+1&&departure){const next=state.cityDates[state.cities[index]];next.start=departure;if(next.end&&next.end<departure){next.end='';next.endChosen=''}}
 state.planningIndex=index;persist();render();
 if(retainedRail){const fresh=document.querySelector('.city-date-row');const freshDays=[...fresh.children];fresh.replaceWith(retainedRail);retainedRail.scrollLeft=previousLeft;retainedRail.getBoundingClientRect();[...retainedRail.children].forEach((day,j)=>{const next=freshDays[j];if(!next)return;day.className=next.className;day.disabled=next.disabled;day.setAttribute('aria-pressed',next.getAttribute('aria-pressed'));day.setAttribute('aria-label',next.getAttribute('aria-label'))})}
 const rail=document.querySelector('.city-date-row'),arrival=rail?.querySelector('.arrival');
 if(rail){rail.scrollLeft=previousLeft;const target=Math.max(0,Math.min(rail.scrollWidth-rail.clientWidth,(arrival?.offsetLeft||0)-(rail.firstElementChild?.offsetLeft||0)));rail.scrollTo({left:target,behavior:reduced?'auto':'smooth'})}
 if(reduced)return;
 document.querySelectorAll('.route-vector path').forEach((n,j)=>n.animate([{strokeDasharray:'1',strokeDashoffset:1},{strokeDasharray:'1',strokeDashoffset:0}],{duration:550,delay:100+j*45,easing:'cubic-bezier(.22,1,.36,1)',fill:'both'}));
 document.querySelectorAll('.route-vector circle').forEach(n=>n.animate([{opacity:0},{opacity:1}],{duration:300,delay:200,fill:'both'}));
 document.querySelectorAll('[data-planning-city]').forEach(n=>{const old=positions.get(n.dataset.planningCity);if(!old)return;const box=n.getBoundingClientRect();n.animate([{transform:`translateX(${old.left-box.left}px)`},{transform:'translateX(0)'}],{duration:720,easing:'cubic-bezier(.22,1,.36,1)'})});
 document.querySelector('.planning-cover>img')?.animate([{opacity:.3},{opacity:1}],{duration:650,easing:'ease-out'});
 await Promise.all([morphCityLabel(incoming,document.querySelector('.planning-cover h1')),morphCityLabel(outgoing,document.querySelector(`[data-planning-city="${previous}"]`))]);
 }finally{cityTransitionBusy=false}
}

function cityCoverPhoto(c){return c==='Paris'?'assets/figma/paris.png':c==='Amsterdam'?'assets/cities/amsterdam-night.jpg':'assets/cities/'+c.toLowerCase()+'.jpg'}
let expandedTripCity = referenceFixture?.expandedCity || null;
let tripDisclosureAnimations=[];
function toggleTripCity(index){
 const app=$('#app'),scroll=app.scrollTop;
 const before=new Map([...document.querySelectorAll('.trip-stop')].map((row,i)=>{const panel=row.querySelector('[id^="trip-itinerary-"]');return [i,{height:panel.getBoundingClientRect().height,html:panel.innerHTML,cover:row.querySelector('.trip-city-cover').getBoundingClientRect().height,titleTop:getComputedStyle(row.querySelector('.trip-city-overlay')).top}]}));
 const oldGap=getComputedStyle(document.querySelector('.trip-city-cards')).gap;
 tripDisclosureAnimations.forEach(animation=>animation.cancel());tripDisclosureAnimations=[];
 const city=state.cities[index];expandedTripCity=expandedTripCity===city?null:city;render();
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(!reduced){
  const timing={duration:720,easing:'cubic-bezier(.25,.1,.25,1)'};
  document.querySelectorAll('.trip-stop').forEach((row,i)=>{
   const previous=before.get(i),panel=row.querySelector('[id^="trip-itinerary-"]'),open=row.classList.contains('is-open');
   const targetHeight=open?panel.getBoundingClientRect().height:0;
   if(previous?.height||open){
    if(!open){panel.innerHTML=previous.html;panel.hidden=false;panel.inert=true;panel.setAttribute('aria-hidden','true');}
    panel.style.overflow='hidden';panel.style.height=(previous?.height||0)+'px';
    const animation=panel.animate([{height:(previous?.height||0)+'px',opacity:previous?.height?1:0},{height:targetHeight+'px',opacity:open?1:0}],timing);
    animation.onfinish=()=>{panel.style.height='';panel.style.overflow='';if(!open){panel.hidden=true;panel.innerHTML='';panel.inert=false;panel.removeAttribute('aria-hidden');}};
    tripDisclosureAnimations.push(animation);
   }
   if(previous){const cover=row.querySelector('.trip-city-cover'),title=row.querySelector('.trip-city-overlay');tripDisclosureAnimations.push(cover.animate([{height:previous.cover+'px'},{height:cover.getBoundingClientRect().height+'px'}],timing),title.animate([{top:previous.titleTop},{top:getComputedStyle(title).top}],timing));}
  });
  const list=document.querySelector('.trip-city-cards');tripDisclosureAnimations.push(list.animate([{gap:oldGap},{gap:getComputedStyle(list).gap}],timing));
 }
 app.scrollTop=scroll;document.querySelector(`[data-trip-city="${index}"]`)?.focus({preventScroll:true});
}

function populateSampleActivities(){
 state.activities??={};state.sampleActivitiesInitialized??={};
 for(const city of state.cities){
  if(state.sampleActivitiesInitialized[city])continue;
  state.sampleActivitiesInitialized[city]=true;
  if(!state.activities[city]?.length)state.activities[city]=tripSuggestions(city).slice(0,3);
 }
}
function tripCityList(){
 populateSampleActivities();
 if(!state.cities.length)return header('Your trip','home')+'<div class="content"><h2>Your next chapter awaits</h2><p class="muted">Choose the cities you want to explore.</p><button class="primary" data-action="new-trip">Create a trip</button></div>';
 return `<div class="content trip-city-list"><div class="figma-trip-heading"><h2>${state.title||'Your trip'}</h2><button class="trip-date-row" data-go="dates" aria-label="Edit trip dates">${state.start?dateLabel(state.start):'Choose dates'}${state.end?' – '+dateLabel(state.end):''}</button><button class="figma-close" data-go="home" aria-label="Close trip"><img src="assets/figma/close.svg" alt="" width="24" height="24"></button></div>${tripVisaCard()}<ol class="trip-city-cards">${state.cities.map((c,i)=>{const open=expandedTripCity===c;return `<li class="trip-stop ${open?'is-open':''}"><button class="trip-city-card" data-trip-city="${i}" aria-expanded="${open}" aria-controls="trip-itinerary-${i}" aria-label="${open?'Collapse':'Open'} ${c} itinerary"><div class="trip-city-cover"><img class="trip-cover-photo" src="${cityCoverPhoto(c)}" alt="${c} city view" loading="${i?'lazy':'eager'}"><div class="trip-city-overlay"><h3>${c}</h3></div></div></button><button class="trip-cover-control" data-reorder-trip-city="${i}" aria-label="Reorder ${c}. Use up and down arrow keys to move."><img class="trip-control-backdrop" src="assets/figma/trip-cover-control-bg.svg" alt=""><img class="trip-control-icon" src="assets/figma/trip-cover-control.svg" width="20" height="20" alt=""></button><div id="trip-itinerary-${i}" ${open?'':'hidden'}>${open?tripItinerary(c,i):''}</div></li>`}).join('')}</ol><p class="sr-only" id="trip-announcement" aria-live="polite"></p></div>`;
}
function tripVisaCard(){return `<section class="trip-visa" aria-label="Visa planning"><span class="trip-passport-shadow" aria-hidden="true"><img src="assets/figma/passport.png" alt=""></span><h3>Do you have a valid visa for this trip?</h3><div>${['Yes','No'].map(v=>`<button data-visa="${v}" aria-pressed="${state.visa===v}"><img src="assets/figma/visa-${v.toLowerCase()}.svg" width="16" height="16" alt="">${v==='Yes'?'yes':v}</button>`).join('')}</div><span class="trip-passport" aria-hidden="true"><img src="assets/figma/passport.png" alt=""></span>${state.visa==='No'?'<p class="visa-note">Add visa planning to your checklist before booking.</p>':''}</section>`}
function tripShortDate(iso){if(!iso)return '';const d=parseDay(iso),n=d.getDate(),suffix=n%100>=11&&n%100<=13?'th':({1:'st',2:'nd',3:'rd'}[n%10]||'th');return n+suffix+' '+d.toLocaleDateString('en-GB',{month:'short'});}
function tripSuggestions(c){return c==='Paris'?['Explore the Louvre','Visit the Musée d’Orsay','See the Eiffel Tower','Walk along the Seine','Spend a morning in Montmartre']:cityIdeas[c]||[];}
function tripExperienceLink(c,a){return {'Explore the Louvre':'https://www.louvre.fr/en/visit','Visit the Musée d’Orsay':'https://www.musee-orsay.fr/en/visit','See the Eiffel Tower':'https://www.toureiffel.paris/en/rates-opening-times'}[a]||'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(a+' '+c);}
function tripItinerary(c,i){
 const chosen=state.activities?.[c]||[],r=state.cityDates?.[c],next=state.cities[i+1],ideas=[...new Set([...tripSuggestions(c),...chosen])];
 const arrival=r?.start||state.start,departure=r?.end||arrival;const allBooked=chosen.length>0&&chosen.every(a=>state.bookedActivities?.includes(a));
 const freeDays=arrival&&departure?Math.max(0,Math.round((parseDay(departure)-parseDay(arrival))/86400000)):0;
 const freeStart=arrival?parseDay(arrival):null;if(freeStart)freeStart.setDate(freeStart.getDate()+1);
 return `<section class="trip-itinerary" aria-label="${c} itinerary"><h3 class="itinerary-day-heading">${tripShortDate(arrival)||'Your itinerary'}</h3><ol class="itinerary-activities" data-activity-city="${i}"><li class="trip-check-in" data-itinerary-index="checkin"><div class="itinerary-activity-card"><span class="booking-checkin-icon"><img src="assets/booking/base-imgFrame1.svg" alt="" width="24" height="24"></span><span>Check-in</span><a class="itinerary-book" href="https://www.google.com/travel/hotels?q=${encodeURIComponent('Hotels in '+c)}" target="_blank" rel="noopener">Find a hotel</a></div><button class="itinerary-drag" data-itinerary-drag="${i}|checkin" aria-label="Reorder check-in. Use up and down arrow keys to move."><img src="assets/figma/trip-drag.svg" width="20" height="20" alt=""></button></li>${chosen.map((a,j)=>`<li data-itinerary-index="${j}"><div class="itinerary-activity-card"><img src="${tripActivityPhoto(c,a)}" alt="" width="56" height="48"><span>${a}</span><a class="itinerary-book" href="${tripExperienceLink(c,a)}" target="_blank" rel="noopener">${/Louvre|Orsay|Eiffel|Museum|Museums|Pantheon|Güell|Família|Palace|Rijksmuseum/.test(a)?'Book tickets':'Explore'}</a></div><button class="itinerary-drag" data-itinerary-drag="${i}|${j}" aria-label="Reorder ${a}. Use arrow keys to move, or Delete to remove."><img src="assets/figma/trip-drag.svg" width="20" height="20" alt=""></button></li>`).join('')}</ol>${freeDays&&!allBooked?`<div class="itinerary-free-days"><h3>${tripShortDate(localDate(freeStart))}${freeDays>1?' – '+tripShortDate(departure):''}</h3><p>You have ${freeDays} free ${freeDays===1?'day':'days'}</p></div>`:''}${ideas.length&&!allBooked?`<section class="trip-suggestions"><h3>Things to do in ${c}</h3><div class="trip-suggestion-rail">${ideas.filter(a=>!chosen.includes(a)).map(a=>{const selected=chosen.includes(a);return `<button data-trip-toggle="${i}|${encodeURIComponent(a)}" aria-pressed="${selected}" aria-label="${selected?'Remove':'Add'} ${a} ${selected?'from':'to'} itinerary"><img src="${tripActivityPhoto(c,a)}" alt="" width="113" height="113" loading="lazy"><span>${a}</span><span class="trip-add-icon" aria-hidden="true">${selected?'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m9 12 2 2 4-4"/></svg>':'<img src="assets/lucide-plus.svg" width="20" height="20" alt="">'}</span></button>`}).join('')}</div></section>`:''}${currentTicket(c)?tripSavedTicketRow(c,next):next?`<section class="trip-transfer"><img class="trip-transfer-marker" src="assets/figma/trip-marker.svg" width="24" height="24" alt=""><h3>${c} <img src="assets/figma/transfer-arrow.svg" width="16" height="16" alt="to"> ${next}</h3><p>${c==='Paris'&&next==='Interlaken'?'Take a day train for the best views of the Swiss Alps and lakes in Interlaken. Take a left side window seat for the best experience.':'Explore transport options for your journey to '+next+'.'}</p><div><a href="https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(c)}&destination=${encodeURIComponent(next)}&travelmode=transit" target="_blank" rel="noopener"><img src="assets/figma/transfer-train.svg" width="20" height="20" alt="">Trains</a><a href="https://www.google.com/travel/flights?q=${encodeURIComponent('Flights from '+c+' to '+next)}" target="_blank" rel="noopener"><img src="assets/figma/transfer-flight.svg" width="20" height="20" alt="">Flights</a><a href="https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(c)}&destination=${encodeURIComponent(next)}&travelmode=transit&transit_mode=bus" target="_blank" rel="noopener"><img src="assets/figma/transfer-bus.svg" width="20" height="20" alt="">Bus</a></div></section>`:''}<button class="sr-only" data-edit-city="${i}">Edit ${c} dates and city guide</button></section>`;
}
