 const [index,value]=button.dataset.tripToggle.split('|'),city=state.cities[Number(index)],activity=decodeURIComponent(value),app=$('#app'),scroll=app.scrollTop;
 state.activities??={};state.activities[city]??=[];const selected=state.activities[city].includes(activity);
