 state.activities[city]=selected?state.activities[city].filter(a=>a!==activity):[...state.activities[city],activity];persist();render();app.scrollTop=scroll;
 const list=document.querySelector(`.itinerary-activities[data-activity-city="${index}"]`);const item=list?.querySelector(`[data-itinerary-index="${state.activities[city].length-1}"]`);const target=item?.querySelector('.itinerary-activity-card');
 if(ghost&&target){target.style.visibility='hidden';const box=target.getBoundingClientRect();const destination=Math.max(0,app.scrollTop+box.top-app.getBoundingClientRect().top-110);app.scrollTo({top:destination,behavior:'smooth'});await new Promise(resolve=>setTimeout(resolve,280));const end=target.getBoundingClientRect();const animation=ghost.animate([{transform:'translate(0,0)',width:source.width+'px',height:source.height+'px',borderRadius:'16px'},{transform:`translate(${end.left-source.left}px,${end.top-source.top}px)`,width:end.width+'px',height:end.height+'px',borderRadius:'16px'}],{duration:620,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'});await animation.finished.catch(()=>{});ghost.remove();target.style.visibility='';target.animate([{opacity:.4,transform:'scale(.98)'},{opacity:1,transform:'scale(1)'}],{duration:180});}else ghost?.remove();
